        getPerformanceSummary(history) {
            if (!history.length) return {};

            var lastRecord = history[history.length - 1];
            var r = lastRecord.results || {};
            var finalSafety = r.psychSafety || 55;
            var finalPerf = r.teamPerformance || 72;
            var finalWellbeing = r.wellbeingQuality || 0;
            var finalAttrition = r.attritionRisk || 50;
            var finalLegal = r.legalCompliance || 100;
            var finalManager = r.managerWellbeing || 58;

            var composite = Math.round((finalSafety + finalPerf + finalWellbeing + (100 - finalAttrition) + finalLegal + finalManager) / 6);

            var t = window.mySimulation.t.bind(window.mySimulation);
            var performance = t('perf_developing');
            if (composite >= 80) performance = t('perf_exceptional');
            else if (composite >= 65) performance = t('perf_effective');
            else if (composite >= 50) performance = t('perf_competent');

            var insights = [];
            if (finalSafety >= 70) insights.push(t('insight_safety_strong'));
            if (finalSafety < 50) insights.push(t('insight_safety_weak'));
            if (finalWellbeing >= 70) insights.push(t('insight_wellbeing_strong'));
            if (finalWellbeing < 40) insights.push(t('insight_wellbeing_weak'));
            if (finalAttrition <= 35) insights.push(t('insight_attrition_low'));
            if (finalAttrition > 65) insights.push(t('insight_attrition_high'));
            if (finalLegal >= 90) insights.push(t('insight_legal_strong'));
            if (finalLegal < 70) insights.push(t('insight_legal_weak'));
            if (finalManager >= 70) insights.push(t('insight_manager_strong'));
            if (finalManager < 45) insights.push(t('insight_manager_weak'));

            return {
                compositeScore: composite,
                performance: performance,
                finalSafety: finalSafety,
                finalPerf: finalPerf,
                finalWellbeing: finalWellbeing,
                finalAttrition: finalAttrition,
                finalLegal: finalLegal,
                finalManager: finalManager,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.psychSafety < 40) return window.mySimulation.t('hint_low_safety');
            if (results.attritionRisk > 70) return window.mySimulation.t('hint_high_attrition');
            if (results.managerWellbeing < 40) return window.mySimulation.t('hint_manager_burnout');
            if (results.wellbeingScore < 30) return window.mySimulation.t('hint_low_wellbeing');
            if (results.wellbeingScore >= 75) return window.mySimulation.t('hint_good_round');
            return null;
        }

